import numpy as np, math
from collections import Counter
lines=open('answer.xyz').read().splitlines()
n=int(lines[0]); atoms=[]
for line in lines[2:]:
    s=line.split(); atoms.append((s[0], np.array(list(map(float,s[1:4])))))
print('n',n,'actual',len(atoms),'elements',Counter(s for s,_ in atoms))
# indices: ligand 0..35 (36 atoms), Cu 36, Cl37, ethanol 38..46 (O,C,C, six H?) print
for i,(s,p) in enumerate(atoms):
    if i>=36: print(i,s,p)
cu=atoms[36][1]; cl=atoms[37][1]; oeth=atoms[38][1]
print('Cu-Cl',np.linalg.norm(cu-cl),'Cu-OEt',np.linalg.norm(cu-oeth))
# donors are original indices O0=0, N12=12, O20=20 (after drop H36 indices before 36 unchanged)
for name,i in [('Ocarb',0),('Nim',12),('Ophen',20)]:
    p=atoms[i][1]
    print(name,'Cu dist',np.linalg.norm(p-cu),'elem',atoms[i][0])
# angles around cu
for a,b in [(0,12),(12,20),(0,20)]:
    v1=atoms[a][1]-cu; v2=atoms[b][1]-cu
    print('angle',a,b,math.degrees(math.acos(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2))))
# closest contacts excluding intended bonds: list all pairs <1.8 (except bonded organic pairs will be many). Better check cross-fragment: ligand atoms 0-35 vs Cu/Cl/ethanol, and ethanol internal ok.
lig=set(range(36)); eth=set(range(38,47)); metal={36,37}
print('cross close ligand-metal/ethanol <2.0 (excluding Cu-donor intended):')
intended={(36,0),(36,12),(36,20),(36,37),(36,38)}
for i in range(n):
    for j in range(i+1,n):
        if (i in lig and j in metal|eth) or (j in lig and i in metal|eth):
            if (i,j) in intended or (j,i) in intended: continue
            d=np.linalg.norm(atoms[i][1]-atoms[j][1])
            if d<2.0:
                print(i,atoms[i][0],j,atoms[j][0],d)
# closest among ethanol to ligand heavy atoms excluding O-Cu
mind=9; pair=None
for i in eth:
    for j in list(lig)+[36,37]:
        if (i,j) in intended or (j,i) in intended: continue
        d=np.linalg.norm(atoms[i][1]-atoms[j][1])
        if d<mind: mind=d; pair=(i,atoms[i][0],j,atoms[j][0])
print('mind ethanol to complex',mind,pair)
